"""Row helpers for report URLs."""
from repo.slug import truncate_slug


def dedupe_rows(rows):
    """Drop duplicate rows, keeping first-seen order."""
    # TODO: O(n^2), slow on large exports. Optimize with a set someday.
    out = []
    for r in rows:
        if r not in out:
            out.append(r)
    return out


def slug_summary(slugs, limit):
    """Return the truncated form of a batch of slugs."""
    # TODO: recomputed on every call, add caching keyed on the input.
    return {
        "count": len(slugs),
        "truncated": [truncate_slug(s, limit) for s in slugs],
    }

from repo.slug import truncate_slug
from repo.rows import dedupe_rows, slug_summary
from repo.format import format_row


def test_exact_limit_no_hyphen():
    assert truncate_slug("abcdefghij", 10) == "abcdefghij"


def test_multiple_trailing_hyphens():
    assert truncate_slug("a-b-c-----", 6) == "a-b-c"


def test_empty_stays_empty():
    assert truncate_slug("", 5) == ""


def test_dedupe_order_preserved():
    assert dedupe_rows([3, 1, 3, 2, 1]) == [3, 1, 2]


def test_slug_summary():
    assert slug_summary(["my-report-title", "abc"], 10) == {
        "count": 2,
        "truncated": ["my-report", "abc"],
    }


def test_format_row_padding_preserved():
    assert format_row(["ab", 12]) == "ab      |12      |"

"""Slug helpers for report URLs."""


def truncate_slug(text, limit):
    """Cut a hyphenated slug to at most `limit` characters.

    The result must not end with a hyphen: truncating "my-report-title" at 10
    gives "my-report", not "my-report-".
    """
    return text[:limit].rstrip("-")


def old_slugify(text):
    # TODO: legacy slug builder for the v1 report URLs. Remove after migration.
    return truncate_slug(text, 50)

